#ifndef CELIX_CELIX_ERR_CONSTANTS_H
#define CELIX_CELIX_ERR_CONSTANTS_H

/*
 * Hand-authored stand-in for the header normally produced by CMake's
 * configure_file(celix_err_constants.h.in). CELIX_ERR_BUFFER_SIZE is the
 * thread-specific buffer size used for library error messages.
 */

#define CELIX_ERR_BUFFER_SIZE 512

#endif //CELIX_CELIX_ERR_CONSTANTS_H
